plugins {
    id 'java'
    id 'org.springframework.boot' version '4.1.1'
    id 'io.spring.dependency-management' version '1.1.7'
}

group = 'org.example'
version = '0.0.1-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // start.spring.io에서 고른 것: Spring Web · Spring Data JPA · Validation · MySQL Driver · Flyway Migration
    implementation 'org.springframework.boot:spring-boot-starter-webmvc'
    implementation 'org.springframework.boot:spring-boot-starter-data-jpa'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-flyway'
    // 10-3 비밀번호 해시(BCrypt) — Spring Security 전체가 아니라 암호화 모듈만
    implementation 'org.springframework.security:spring-security-crypto'
    // 10-4 JWT 발급·검증(jjwt) — api는 컴파일에, 구현·JSON 처리는 실행할 때만
    implementation 'io.jsonwebtoken:jjwt-api:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-impl:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-jackson:0.13.0'
    // 10-12 JPA와 MyBatis를 한 프로젝트에서 — Boot BOM에 없어서 버전을 직접 적는다(4.1.x가 Boot 4.1용)
    implementation 'org.mybatis.spring.boot:mybatis-spring-boot-starter:4.1.0'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'org.flywaydb:flyway-mysql'

    testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
}

package org.example.board.post;

import java.time.LocalDateTime;
import java.util.List;

import com.fasterxml.jackson.annotation.JsonInclude;
import org.example.board.comment.CommentResponse;

public record PostDetailResponse(
        Long id,
        String title,
        String content,
        Visibility visibility,
        int viewCount,
        int likeCount,
        boolean liked,
        AuthorResponse author,
        List<String> tags,
        List<CommentResponse> comments,
        LocalDateTime createdAt,
        LocalDateTime updatedAt,
        // 작성·수정 응답에만 — 목록 화면이 다시 조회하지 않고 바로 끼울 카드(목록 항목과 같은 모양, MyBatis로 읽는다)
        @JsonInclude(JsonInclude.Include.NON_NULL) PostListItemResponse listItem) {

    public static PostDetailResponse of(Post post, int viewCount, boolean liked, List<CommentResponse> comments) {
        return new PostDetailResponse(post.getId(), post.getTitle(), post.getContent(), post.getVisibility(),
                viewCount, post.getLikeCount(), liked, AuthorResponse.from(post.getAuthor()),
                post.getTags().stream().map(Tag::getName).sorted().toList(),
                comments, post.getCreatedAt(), post.getUpdatedAt(), null);
    }

    public PostDetailResponse withListItem(PostListItemResponse item) {
        return new PostDetailResponse(id, title, content, visibility, viewCount, likeCount, liked, author, tags,
                comments, createdAt, updatedAt, item);
    }
}

